"""Wire ``on_tool_result`` / ``modify_tool_result`` after each tool dispatch."""

from __future__ import annotations

from typing import Any, NamedTuple

import structlog

from rasa.mantle.hooks.constants import POINT_TOOL_RESULT
from rasa.mantle.hooks.exceptions import HookExecutionError
from rasa.mantle.hooks.payloads import ToolResultPayload
from rasa.mantle.hooks.registry import HookRegistry
from rasa.mantle.hooks.runner import run_modify, run_observers
from rasa.mantle.hooks.utils import hook_identity

structlogger = structlog.get_logger()


class ToolResultHookOutcome(NamedTuple):
    """Persisted tool result after optional ``modify_tool_result``."""

    value: Any
    is_error: bool
    arguments: dict[str, Any]


async def apply_tool_result_hooks(
    registry: HookRegistry,
    *,
    tool_name: str,
    arguments: dict[str, Any],
    value: Any,
    is_error: bool,
) -> ToolResultHookOutcome:
    """Run ``on_tool_result`` / ``modify_tool_result`` for one dispatched call.

    Observers fire-and-forget. The modify lane may rewrite ``value``,
    ``arguments``, and ``is_error``. This point has no control signals;
    unexpected crashes, timeouts, or ``HookExecutionError`` from the runner
    are fail-open and keep the original result.
    """
    if (
        not registry.observers(POINT_TOOL_RESULT)
        and registry.modifier(POINT_TOOL_RESULT) is None
    ):
        return ToolResultHookOutcome(
            value=value, is_error=is_error, arguments=dict(arguments)
        )

    try:
        sender_id, channel = hook_identity()
    except LookupError:
        # Live turns establish MessageTurnContext; missing context is misuse
        # (e.g. isolated unit tests). Keep the result unmodified.
        structlogger.warning(
            "mantle.hooks.tool_result.skipped_no_turn_context",
        )
        return ToolResultHookOutcome(
            value=value, is_error=is_error, arguments=dict(arguments)
        )

    payload = ToolResultPayload(
        sender_id=sender_id,
        channel=channel,
        tool_name=tool_name,
        arguments=dict(arguments),
        value=value,
        is_error=is_error,
    )

    run_observers(registry, POINT_TOOL_RESULT, payload)
    try:
        result = await run_modify(registry, POINT_TOOL_RESULT, payload)
    except HookExecutionError:
        # Fail-open backstop: the runner re-raises typed HookExecutionError
        # from the hook itself; keep the original dispatched result.
        return ToolResultHookOutcome(
            value=value, is_error=is_error, arguments=dict(arguments)
        )

    modified = result.payload
    if not isinstance(modified, ToolResultPayload):
        # Fail-open: keep the original result rather than aborting the turn.
        return ToolResultHookOutcome(
            value=value, is_error=is_error, arguments=dict(arguments)
        )

    return ToolResultHookOutcome(
        value=modified.value,
        is_error=modified.is_error,
        arguments=dict(modified.arguments),
    )
